#!/usr/bin/env node
/* gen-seam-card.mjs — the Wave B #1 generated provenance surface (the highest-convergence idea of
 * the four 2026-11-25 reviews: hy4 #3, porca N1, pickle A1, ernie A1).
 *
 * ONE generated file — seam-card.json at the tree root — compiles the provenance facts the shell's
 * dev-gated footer chip AND the packaging gate both read. One file, two consumers, zero drift:
 *   • pin + stamp        ← SNAPSHOT.md (the contract of record, parsed — never hardcoded)
 *   • engineVersion      ← the RUNNING engine (imported through the ONE door, node-side)
 *   • sealCount          ← CHECKSUMS.txt line count (the same number verify-package prints)
 *   • claims             ← claims.json (total + phase counts)
 *   • dist               ← the dist fingerprint (the same walk shell-status/statusFreshness use)
 *   • generated inputs   ← sha256 of every file this card was built from (the freshness discipline)
 *
 * The chip (src/lib/components/SeamCard.svelte, ?dev-gated) renders UNKNOWN for any field it cannot
 * resolve — never a green default — and the boot-time pin canary (App.svelte) compares the RUNNING
 * engineVersion() stamp against the card's stamp; a mismatch renders UNKNOWN, never green.
 *
 * Run: node --import ./scripts/node-port-register.mjs scripts/gen-seam-card.mjs
 * (regenerate at the final bytes — the seal count it embeds changes at every reseal)
 */
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';

const ROOT = path.resolve(new URL('..', import.meta.url).pathname);
const sha = (rel) => createHash('sha256').update(fs.readFileSync(path.join(ROOT, rel))).digest('hex');

// the pin + stamp, parsed from SNAPSHOT.md — the contract of record (shell-status reads it the same way)
const snap = fs.readFileSync(path.join(ROOT, 'SNAPSHOT.md'), 'utf8');
const pin = (snap.match(/Engine commit: `([0-9a-f]{8,9})`/) || [])[1] ?? null;
const stamp = (snap.match(/`([a-z0-9]+\.[0-9a-f]{12,})`/) || [])[1] ?? null;   // the first backticked engine-stamp token (the 'x.yyyy...' shape — pack hashes use ':' and pins have no dot, so this is the self-declared stamp unambiguously)
if (!pin) { console.error('gen-seam-card: SNAPSHOT.md names no engine commit — refusing to emit a card with an UNKNOWN pin'); process.exit(1); }

// the RUNNING engine, through the ONE door (this script runs node-side with the register hook)
const port = await import(path.join(ROOT, 'src/lib/port/seam.ts'));
const running = port.engineVersion();
const stampOk = stamp && running && String(running).includes(stamp.replace(/^[a-z0-9]+\./, ''));

// the seal count — the same lines verify-package counts
const sealCount = fs.readFileSync(path.join(ROOT, 'CHECKSUMS.txt'), 'utf8').split('\n').filter((l) => l.trim()).length;

// the claims summary
const claims = JSON.parse(fs.readFileSync(path.join(ROOT, 'claims.json'), 'utf8'));
const claimTotal = claims.claims.length;
const claimPackaging = claims.claims.filter((c) => (c.phases || ['full']).includes('packaging')).length;

// the dist fingerprint (the same walk tools/shell-status.mjs uses)
const h = createHash('sha256');
const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else h.update(path.relative(ROOT, p) + ':' + createHash('sha256').update(fs.readFileSync(p)).digest('hex') + '\n'); } };
const distDir = path.join(ROOT, 'dist');
const distHash = fs.existsSync(distDir) ? (walk(distDir), h.digest('hex')) : null;

const INPUTS = ['SNAPSHOT.md', 'claims.json', 'CHECKSUMS.txt'];
const card = {
  meta: 'GENERATED by scripts/gen-seam-card.mjs — do not edit. ONE provenance file read by BOTH the dev-gated SeamCard chip (src/lib/components/SeamCard.svelte) and the claims gate (claims.json row seam-card-agrees). Any missing field renders UNKNOWN in the chip — never a green default.',
  generated: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
  pin,
  stampSnapshot: stamp,
  engineVersionRunning: running ?? null,
  stampCanary: stampOk ? 'match' : 'UNKNOWN',
  sealCount,
  claims: { total: claimTotal, packagingPhase: claimPackaging, file: 'claims.json', command: 'node scripts/check-claims.mjs' },
  distHash,
  inputs: Object.fromEntries(INPUTS.map((i) => [i, sha(i)])),
};
fs.writeFileSync(path.join(ROOT, 'seam-card.json'), JSON.stringify(card, null, 1) + '\n');
console.log(`gen-seam-card: seam-card.json written (pin ${pin}, seal ${sealCount}, claims ${claimTotal}, stamp canary ${card.stampCanary})`);
